import shutil
from pathlib import Path

from click.testing import CliRunner

from dograpper.commands.pack import pack
from dograpper.utils.redirect_stub import find_redirect_stub_files, is_redirect_stub

# Generated by tests/fixtures/rustdoc_redirect/regenerate.sh (rustdoc 1.96): never edit by hand.
FIXTURE = Path(__file__).parent / "fixtures" / "rustdoc_redirect" / "html" / "fixture"
STUB = (FIXTURE / "imp" / "fn.kmerge_by.html").read_bytes()

REFRESH_LONG = ("<html><head><meta http-equiv=\"refresh\" content=\"5; url=/new/\"><title>Moved</title></head>"
                "<body><h1>Moved</h1><p>%s</p></body></html>" % " ".join(["real documentation"] * 40))
REAL = ("<html><head><title>Overview</title></head><body><h1>Overview</h1>"
        "<p>%s</p></body></html>" % " ".join(["real documentation"] * 40))


def test_is_redirect_stub():
    assert is_redirect_stub(STUB)
    assert is_redirect_stub(b"<meta http-equiv=refresh content='0; URL=a.html'><p>Redirecting...</p>")
    assert not is_redirect_stub(REAL.encode())
    assert not is_redirect_stub(REFRESH_LONG.encode())  # a refresh with more than 40 visible words
    assert not is_redirect_stub(b'<meta http-equiv="refresh" content="30"><p>Reloading</p>')  # no URL
    assert not is_redirect_stub((FIXTURE / "fn.kmerge_by.html").read_bytes())  # the real page


def test_find_redirect_stub_files_ignores_non_html(tmp_path):
    (tmp_path / "a.html").write_bytes(STUB)
    (tmp_path / "b.md").write_bytes(STUB)
    assert find_redirect_stub_files([str(tmp_path / "a.html"), str(tmp_path / "b.md")]) == [
        str(tmp_path / "a.html")]


def _make_input(tmp_path):
    src = tmp_path / "docs"
    (src / "imp").mkdir(parents=True)
    shutil.copy(FIXTURE / "fn.kmerge_by.html", src / "fn.kmerge_by.html")
    (src / "imp" / "fn.kmerge_by.html").write_bytes(STUB)
    (src / "moved.html").write_text(REFRESH_LONG)
    return src


def test_pack_skips_redirect_stubs_and_reports_them(tmp_path):
    src = _make_input(tmp_path)
    result = CliRunner().invoke(pack, [str(src), "-o", str(tmp_path / "out")])
    assert result.exit_code == 0, result.output
    assert result.output.count("redirect stub page") == 1
    assert "imp/fn.kmerge_by.html" in result.output
    assert "Redirect stubs: 1" in result.output
    assert "Files processed: 2" in result.output and "Files excluded:  1" in result.output
    assert "Redirect aliases" not in result.output


def test_pack_page_layout_skips_redirect_stubs(tmp_path):
    src = _make_input(tmp_path)
    out = tmp_path / "out"
    result = CliRunner().invoke(pack, [str(src), "-o", str(out), "--layout", "page"])
    assert result.exit_code == 0, result.output
    assert "Redirect stubs: 1" in result.output
    assert len(list((out / "pages").glob("*.md"))) == 2


def test_pack_dry_run_skips_redirect_stubs(tmp_path):
    src = _make_input(tmp_path)
    result = CliRunner().invoke(pack, [str(src), "-o", str(tmp_path / "out"), "--dry-run"])
    assert result.exit_code == 0, result.output
    assert "redirect stub page" in result.output and "imp/fn.kmerge_by.html" in result.output
    assert not (tmp_path / "out").exists()


def test_pack_fails_loud_when_every_page_is_a_redirect_stub(tmp_path):
    src = tmp_path / "docs"
    src.mkdir()
    (src / "a.html").write_bytes(STUB)
    result = CliRunner().invoke(pack, [str(src), "-o", str(tmp_path / "out")])
    assert result.exit_code != 0
    assert "redirect stub" in result.output
